```gq
gq 3;

query colleagues($of: String) {
  match {
    $p: Person { handle: $of }
    $p worksAt $c
    $q worksAt $c
    $q.handle != $p.handle
  }
  return { $q }
}

query colleagues_of_colleagues($of: String) {
  match {
    from { match { from colleagues($of) } return { $q.handle as h1 } }
    from colleagues($h1)
  }
  return distinct { $q.name }
}
